import{_ as t}from"./chunks/Audio.COine8Wh.js";import{c as r,o,j as i,G as n,ae as a,a as s}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"ORDERING THE REFORM OF THE NUCLEAR REGULATORY COMMISSION","description":"","frontmatter":{"legisId":"2025-05-23-ordering-the-reform-of-the-nuclear-regulatory-commission","title":"ORDERING THE REFORM OF THE NUCLEAR REGULATORY COMMISSION","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/ordering-the-reform-of-the-nuclear-regulatory-commission/","publishDate":"2025-05-23T17:28:55-04:00","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Executive Orders\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"ORDERING THE REFORM OF THE NUCLEAR REGULATORY COMMISSION\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders/2025-05-23-ordering-the-reform-of-the-nuclear-regulatory-commission\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"ORDERING THE REFORM OF THE NUCLEAR REGULATORY COMMISSION\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/executive-orders/2025-05-23-ordering-the-reform-of-the-nuclear-regulatory-commission\\",\\"datePublished\\":\\"2025-05-23T17:28:55-04:00\\",\\"dateModified\\":1769822760000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/executive-orders/2025-05-23-ordering-the-reform-of-the-nuclear-regulatory-commission\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"executive-orders/2025-05-23-ordering-the-reform-of-the-nuclear-regulatory-commission.md","filePath":"executive-orders/2025-05-23-ordering-the-reform-of-the-nuclear-regulatory-commission.md","lastUpdated":1769822760000}'),l={name:"executive-orders/2025-05-23-ordering-the-reform-of-the-nuclear-regulatory-commission.md"},p=Object.assign(l,{setup(c){return(u,e)=>(o(),r("div",null,[e[0]||(e[0]=i("h1",{id:"ordering-the-reform-of-the-nuclear-regulatory-commission",tabindex:"-1"},[s("ORDERING THE REFORM OF THE NUCLEAR REGULATORY COMMISSION "),i("a",{class:"header-anchor",href:"#ordering-the-reform-of-the-nuclear-regulatory-commission","aria-label":'Permalink to "ORDERING THE REFORM OF THE NUCLEAR REGULATORY COMMISSION"'},"​")],-1)),n(t),e[1]||(e[1]=a('<p>Published on Friday, May 23, 2025</p><ul><li><p><strong>Authority and Importance of Nuclear Energy</strong></p><ul><li>Energy is a crucial aspect of national and economic security.</li><li>Domestic fossil fuel and nuclear energy can reduce dependence on geopolitical rivals.</li><li>Nuclear power supports traditional and advanced industries, including AI and quantum computing.</li></ul></li><li><p><strong>Historical Context</strong></p><ul><li>133 nuclear reactors were built from 1954 to 1978; only two have been commercially operated since then.</li><li>The NRC has inefficiently processed licensing, contributing to limited nuclear power development despite technological advancements.</li></ul></li><li><p><strong>NRC Failures and Policy Shift</strong></p><ul><li>The NRC has focused on minimizing risks without adequately considering economic and security implications.</li><li>Current safety models lack a sound basis, leading to irrational regulatory outcomes.</li></ul></li><li><p><strong>Administrative Actions</strong></p><ul><li>Focus on reliable power sources, like nuclear, over intermittent energy sources.</li><li>Reform the NRC&#39;s structure, personnel, regulations, and operations to enhance nuclear energy deployment.</li></ul></li><li><p><strong>Policy Directives</strong></p><ul><li>Reestablish U.S. leadership in nuclear energy.</li><li>Encourage new reactor technologies while reducing regulatory and cost barriers.</li><li>Increase nuclear energy capacity from 100 GW in 2024 to 400 GW by 2050.</li><li>Integrate innovative technologies for reactor design approval.</li></ul></li><li><p><strong>NRC Reorganization and Regulations</strong></p><ul><li>Restructure the NRC to expedite license processing and support innovative technology.</li><li>Review and revise NRC regulations and guidance documents within specified deadlines.</li><li>Establish fixed deadlines for decision-making on applications to enhance efficiency.</li><li>Adopt science-based radiation limits and revise environmental compliance regulations.</li></ul></li><li><p><strong>Licensing Process Improvements</strong></p><ul><li>Create an expedited pathway for tested reactor designs.</li><li>Streamline high-volume licensing processes for modular and microreactors.</li><li>Update the reactor oversight process to minimize unnecessary burdens.</li></ul></li><li><p><strong>Implementation Provisions</strong></p><ul><li>The order does not limit existing authorities of executive departments or the OMB.</li><li>Implementation is subject to applicable laws and available appropriations.</li><li>The order does not create enforceable rights or benefits against the U.S. or its entities.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/ordering-the-reform-of-the-nuclear-regulatory-commission/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/ordering-the-reform-of-the-nuclear-regulatory-commission/</a></p>',3))]))}});export{g as __pageData,p as default};
